-- Durable Bajaj spare-parts product master, separate from dealership stock and balances.
-- BGP codes are QuantaEdge catalogue references, NOT Bajaj OEM part numbers.
-- No OEM numbers, dealership prices, stock quantities or motorcycle fitment are fabricated.
create table bajaj_spare_part_catalogue (
 id bigint generated by default as identity primary key, public_id uuid not null default gen_random_uuid() unique,
 catalogue_code varchar(60) not null unique, part_name varchar(200) not null,
 category varchar(32) not null check (category in ('ENGINE','BRAKES','CLUTCH','TRANSMISSION','FILTERS','ELECTRICAL','LIGHTING','SUSPENSION','BODY','CONTROLS','FUEL_SYSTEM','FLUIDS','WHEELS','ACCESSORIES','OTHER')),
 description varchar(1000), unit_of_measure varchar(16) not null default 'EACH' check (unit_of_measure in ('EACH','PAIR','SET','LITRE','ML','GRAM','KG','METER')),
 oem_part_number varchar(100), fitment_model_codes jsonb not null default '[]'::jsonb check (jsonb_typeof(fitment_model_codes) = 'array'),
 image_url text, source_url text, source_verified_at date,
 source_data_status varchar(32) not null default 'UNVERIFIED' check (source_data_status in ('NAME_REFERENCE_ONLY','DEALERSHIP_VERIFIED','UNVERIFIED')),
 is_global_catalogue boolean not null default false, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create index ix_bajaj_spare_catalogue_search on bajaj_spare_part_catalogue(category, active, lower(part_name));

create table retail_part_catalogue_listing (
 dealership_id bigint not null references dealership(id), catalogue_product_id bigint not null references bajaj_spare_part_catalogue(id),
 retail_enabled boolean not null default false, retail_price numeric(14,2) check (retail_price is null or retail_price > 0),
 retail_description varchar(1000), fitment_model_codes jsonb not null default '[]'::jsonb check (jsonb_typeof(fitment_model_codes) = 'array'),
 retail_image_url text, fitment_verified boolean not null default false, updated_by_staff_user_id bigint,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(), primary key (dealership_id, catalogue_product_id),
 constraint fk_retail_catalogue_listing_updater_same_dealership foreign key (dealership_id, updated_by_staff_user_id) references staff_user(dealership_id, id),
 constraint ck_retail_catalogue_listing_price check (not retail_enabled or retail_price is not null)
);
create index ix_retail_catalogue_listing_customer on retail_part_catalogue_listing(dealership_id, retail_enabled, catalogue_product_id);

-- The product master has no inventory foreign key. This optional mapping is controlled by staff.
create table retail_part_catalogue_stock_map (
 dealership_id bigint not null references dealership(id), catalogue_product_id bigint not null references bajaj_spare_part_catalogue(id),
 stock_part_id bigint not null, updated_by_staff_user_id bigint, created_at timestamptz not null default now(), updated_at timestamptz not null default now(),
 primary key (dealership_id, catalogue_product_id), unique (dealership_id, stock_part_id),
 constraint fk_retail_catalogue_stock_part_same_dealership foreign key (dealership_id, stock_part_id) references spare_part(dealership_id, id) on delete cascade,
 constraint fk_retail_catalogue_stock_updater_same_dealership foreign key (dealership_id, updated_by_staff_user_id) references staff_user(dealership_id, id)
);
create index ix_retail_catalogue_stock_map_part on retail_part_catalogue_stock_map(dealership_id, stock_part_id);

