-- Existing dealership SKU records become durable local product records, retaining stable public IDs.
insert into bajaj_spare_part_catalogue(public_id, catalogue_code, part_name, category, description, unit_of_measure, fitment_model_codes, source_data_status, is_global_catalogue)
select part.public_id, 'LEGACY-' || replace(part.public_id::text, '-', ''), part.part_name, 'OTHER', part.description, part.unit_of_measure, coalesce(part.fitment_model_codes, '[]'::jsonb), 'UNVERIFIED', false
from spare_part part on conflict (public_id) do nothing;
insert into retail_part_catalogue_listing(dealership_id, catalogue_product_id, retail_enabled, retail_price, retail_description, fitment_model_codes, retail_image_url, fitment_verified, updated_by_staff_user_id)
select part.dealership_id, catalogue.id, part.retail_enabled, part.retail_price, part.retail_description, coalesce(part.fitment_model_codes, '[]'::jsonb), part.retail_image_url, part.retail_enabled, part.retail_updated_by_staff_user_id
from spare_part part join bajaj_spare_part_catalogue catalogue on catalogue.public_id = part.public_id
on conflict (dealership_id, catalogue_product_id) do nothing;
insert into retail_part_catalogue_stock_map(dealership_id, catalogue_product_id, stock_part_id)
select part.dealership_id, catalogue.id, part.id from spare_part part
join bajaj_spare_part_catalogue catalogue on catalogue.public_id = part.public_id on conflict do nothing;

-- Immutable product identity on old order snapshots; line descriptions/prices remain as captured at checkout.
alter table retail_part_order_line add column catalogue_product_id bigint;
update retail_part_order_line line set catalogue_product_id = catalogue.id
from spare_part part join bajaj_spare_part_catalogue catalogue on catalogue.public_id = part.public_id
where part.dealership_id = line.dealership_id and part.id = line.part_id;
alter table retail_part_order_line alter column catalogue_product_id set not null;
alter table retail_part_order_line add constraint fk_retail_order_line_catalogue_product foreign key (catalogue_product_id) references bajaj_spare_part_catalogue(id);
create index ix_retail_order_line_catalogue_history on retail_part_order_line(catalogue_product_id, created_at desc);

-- New inventory SKUs receive a durable local catalogue candidate through the same receiving workflow,
-- but no stock mapping is created automatically. Staff must explicitly select the correct product.
create or replace function ensure_bajaj_spare_part_catalogue_after_stock_insert() returns trigger language plpgsql as $$
declare catalogue_row_id bigint;
begin
 insert into bajaj_spare_part_catalogue(public_id, catalogue_code, part_name, category, description, unit_of_measure, fitment_model_codes, source_data_status, is_global_catalogue)
 values (new.public_id, 'LOCAL-' || replace(new.public_id::text, '-', ''), new.part_name, 'OTHER', new.description, new.unit_of_measure, coalesce(new.fitment_model_codes, '[]'::jsonb), 'UNVERIFIED', false)
 on conflict (public_id) do nothing;
 select id into catalogue_row_id from bajaj_spare_part_catalogue where public_id = new.public_id;
 insert into retail_part_catalogue_listing(dealership_id, catalogue_product_id, retail_enabled, retail_description, fitment_model_codes, retail_image_url, fitment_verified, updated_by_staff_user_id)
 values (new.dealership_id, catalogue_row_id, false, new.retail_description, coalesce(new.fitment_model_codes, '[]'::jsonb), new.retail_image_url, false, new.retail_updated_by_staff_user_id)
 on conflict (dealership_id, catalogue_product_id) do nothing;
 -- Do not create a stock mapping here. A SKU may correspond to an existing global catalogue product,
 -- so staff must explicitly link the correct catalogue item in the retail workspace.
 return new;
end; $$;
create trigger trg_spare_part_catalogue_after_insert after insert on spare_part for each row execute function ensure_bajaj_spare_part_catalogue_after_stock_insert();
